          "replace": "    def _interest_states(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        real_inputs = seq.ne(0)\n        prefix_count = real_inputs.cumsum(dim=1).clamp(max=20).to(emb.dtype)\n        input_scale = 1.0 + 0.03 * prefix_count / 20.0\n        emb = self.dropout(emb * input_scale.unsqueeze(-1))\n        out, _ = self.gru(emb)"
